using System.Diagnostics;using SobhanNotificationHub.Models;using SobhanNotificationHub.Services;namespace SobhanNotificationHub.UI;public partial class SettingsWindow:System.Windows.Window{public SettingsWindow(){InitializeComponent();var s=App.Services.Settings;var c=App.Services.CurrentConfig;ConnectionText.Text=App.Services.TokenStore.HasCredentials?"وضعیت: متصل":"وضعیت: قطع";UserText.Text=c is null?"":$"کاربر: {c.User.DisplayName} · {c.User.Unit} · {c.User.Role}";SiteText.Text=$"سایت: {s.SiteUrl}";PollText.Text=$"فاصله بررسی (از سایت): {c?.Client.PollSeconds??0} ثانیه";StartupCheck.IsChecked=StartupService.IsEnabled;SoundCheck.IsChecked=s.LocalSoundEnabled;BodyCheck.IsChecked=s.LocalShowBody;}private void Save_Click(object s,RoutedEventArgs e){StartupService.Set(StartupCheck.IsChecked==true);App.Services.Settings.LocalSoundEnabled=SoundCheck.IsChecked==true;App.Services.Settings.LocalShowBody=BodyCheck.IsChecked==true;App.Services.Settings.Save();StatusText.Text="تنظیمات محلی ذخیره شد.";}private async void Test_Click(object s,RoutedEventArgs e){var n=new SobhanNotification{Id=DateTimeOffset.UtcNow.ToUnixTimeSeconds(),Module="system",Title="اعلان آزمایشی سبحان",Body="اتصال اعلان ویندوز به‌درستی کار می‌کند.",SafeBody="یک اعلان آزمایشی دریافت کردید."};await App.Services.Notifier.ShowAsync(n,App.Services.CurrentConfig??new ClientConfig(),CancellationToken.None);}private void Site_Click(object s,RoutedEventArgs e)=>Process.Start(new ProcessStartInfo(App.Services.Settings.SiteUrl.TrimEnd('/')+"/admin/notification-settings.php"){UseShellExecute=true});private async void Disconnect_Click(object s,RoutedEventArgs e){try{await new DeviceRegistrationService(App.Services.Api,App.Services.TokenStore).DisconnectAsync(CancellationToken.None);App.Services.Tray.SetDisconnected();StatusText.Text="اتصال این دستگاه لغو شد.";}catch(Exception ex){LoggingService.Error("disconnect_ui",ex);StatusText.Text="قطع اتصال انجام نشد.";}}}
